CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','accounts','education','attendance','exams')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), admission_no TEXT UNIQUE NOT NULL, name TEXT NOT NULL, father_name TEXT, department TEXT, class_name TEXT, phone TEXT, status TEXT DEFAULT 'active', data JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS staff (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, position TEXT, salary NUMERIC(12,2) DEFAULT 0, data JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), person_type TEXT NOT NULL, person_ref TEXT NOT NULL, attendance_date DATE NOT NULL, status TEXT NOT NULL, method TEXT NOT NULL DEFAULT 'manual', device_id TEXT, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(person_type,person_ref,attendance_date));
CREATE TABLE IF NOT EXISTS fee_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_ref TEXT NOT NULL, fee_period TEXT NOT NULL CHECK(fee_period IN ('monthly','annual')), amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), paid_on DATE NOT NULL, receipt_no TEXT UNIQUE, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS finance_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), direction TEXT NOT NULL CHECK(direction IN ('income','expense')), fund_type TEXT NOT NULL CHECK(fund_type IN ('general','donation','zakat','sadaqah','salary','other')), description TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), transaction_date DATE NOT NULL, reference_no TEXT, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_ref TEXT NOT NULL, exam_name TEXT NOT NULL, subject TEXT NOT NULL, total_marks NUMERIC(8,2) NOT NULL, obtained_marks NUMERIC(8,2) NOT NULL, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_event_id TEXT UNIQUE NOT NULL, entity TEXT NOT NULL, payload JSONB NOT NULL, submitted_by UUID REFERENCES users(id), received_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), action TEXT NOT NULL, entity TEXT, entity_id TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(attendance_date); CREATE INDEX IF NOT EXISTS idx_fee_student ON fee_transactions(student_ref); CREATE INDEX IF NOT EXISTS idx_finance_date ON finance_transactions(transaction_date);
